<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CreativArt — Articole personalizate</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:1200px;margin:auto;padding:22px}.shopbar{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.shopbar input,.shopbar select{padding:11px;border:1px solid #ddd;border-radius:10px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:18px}.card{background:#fff;border-radius:18px;padding:14px;box-shadow:0 8px 30px #0001}.card img{width:100%;height:220px;object-fit:cover;border-radius:14px}.hero2{padding:58px 20px;text-align:center;background:linear-gradient(135deg,#171411,#6d421c);color:#fff}.hero2 h1{font:52px Georgia;margin:0}.hero2 h1 span{color:#e8ad43}.actions{display:flex;gap:8px}.actions button{flex:1;padding:11px;border:0;border-radius:10px}.gold{background:#e8ad43}.cartBtn{position:fixed;right:18px;bottom:18px;background:#111;color:#fff;padding:14px;border-radius:14px;z-index:15}.checkout{margin-top:25px}.checkout input,.checkout textarea{width:100%;padding:10px;margin:5px 0}.drawer{position:fixed;right:0;top:0;width:min(92%,440px);height:100%;background:#fff;z-index:30;padding:24px;box-shadow:-10px 0 30px #0003;overflow:auto}.hidden{display:none}.ci{border-bottom:1px solid #ddd;padding:12px 0}.qty button{padding:5px 9px}.customizer{position:fixed;inset:0;background:#000a;z-index:40;display:grid;place-items:center;padding:15px}.customizer.hidden{display:none}.custombox{background:#fff;width:min(950px,96vw);max-height:92vh;overflow:auto;padding:22px;border-radius:20px}.customgrid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.preview{min-height:380px;background:#eee center/cover no-repeat;border-radius:18px;display:grid;place-items:center;position:relative;overflow:hidden}.preview img.uploaded{max-width:60%;max-height:60%;object-fit:contain}.previewText{position:absolute;bottom:22px;background:#fff9;padding:8px 12px;border-radius:8px;font-weight:bold}.custombox input,.custombox textarea{width:100%;padding:11px;margin:7px 0}.close{float:right;font-size:24px}.old{text-decoration:line-through;color:#888}.price{font-size:21px;color:#c62828}.accountlink{display:inline-block;margin-top:12px;color:#fff}@media(max-width:700px){.customgrid{grid-template-columns:1fr}.preview{min-height:300px}.hero2 h1{font-size:38px}}</style></head><body><div class="hero2"><h1>Creativ<span>Art</span></h1><p>Articole personalizate pentru momente speciale</p><a class="accountlink" href="account.php">👤 Contul meu</a> &nbsp; <a class="accountlink" href="admin/">⚙️ Admin</a></div><main class="wrap"><h2>Produse</h2><div class="shopbar"><input id="search" placeholder="Caută produse..."><select id="category"><option value="">Toate categoriile</option></select><select id="sort"><option value="new">Cele mai noi</option><option value="priceAsc">Preț crescător</option><option value="priceDesc">Preț descrescător</option></select></div><div id="products" class="grid"></div><section class="card checkout"><h2>Finalizează comanda</h2><input id="name" placeholder="Nume și prenume"><input id="email" type="email" placeholder="Email (opțional)"><input id="phone" placeholder="Telefon"><textarea id="address" placeholder="Adresă de livrare"></textarea><textarea id="details" placeholder="Detalii suplimentare"></textarea><button class="gold" onclick="sendOrder()">Trimite comanda</button><p id="msg"></p></section></main><button class="cartBtn" onclick="toggleCart()">🛒 Coș: <span id="count">0</span> · <span id="cartTotal">0,00</span> lei</button><aside id="cart" class="drawer hidden"><button onclick="toggleCart()">✕ Închide</button><h2>Coșul tău</h2><div id="cartItems"></div><h3>Total: <span id="drawerTotal">0,00</span> lei</h3></aside><section id="customizer" class="customizer hidden"><div class="custombox"><button class="close" onclick="closeCustomizer()">✕</button><h2>Personalizează produsul</h2><div class="customgrid"><div id="preview" class="preview"><img id="uploadedPreview" class="uploaded hidden"><div id="previewText" class="previewText"></div></div><div><h3 id="customName"></h3><label>Text personalizat</label><textarea id="personalText" placeholder="Ex: Te iubesc! / La mulți ani!"></textarea><label>Încarcă fotografia ta</label><input id="personalImage" type="file" accept="image/*"><p><small>Previzualizarea este orientativă; poziționarea finală se confirmă înainte de producție.</small></p><button class="gold" onclick="addCustomized()">Adaugă personalizarea în coș</button></div></div></div></section><script src="assets/app.js"></script></body></html>
